package com.pulsesg.support.controller;
import com.pulsesg.support.dto.ApiDtos.*; import com.pulsesg.support.service.PortalService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/tickets") public class TicketController {private final PortalService s;public TicketController(PortalService s){this.s=s;}@GetMapping List<TicketResponse> all(){return s.all().stream().map(s::dto).toList();}@PostMapping ResponseEntity<TicketResponse> create(@Valid @RequestBody TicketRequest r){return ResponseEntity.status(201).body(s.dto(s.create(r)));}@GetMapping("/{id}") TicketResponse get(@PathVariable Long id){return s.dto(s.ticket(id));}@PutMapping("/{id}") TicketResponse update(@PathVariable Long id,@RequestBody TicketUpdate r){return s.dto(s.update(id,r));}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/{id}/messages") List<MessageResponse> messages(@PathVariable Long id){return s.messages(id).stream().map(s::dto).toList();}@PostMapping("/{id}/messages") ResponseEntity<MessageResponse> message(@PathVariable Long id,@Valid @RequestBody MessageRequest r){return ResponseEntity.status(201).body(s.dto(s.message(id,r)));}@PostMapping("/{id}/ai-suggestion") SuggestionResponse suggest(@PathVariable Long id){return new SuggestionResponse(s.suggestion(id));}}
